package library.grader;

import java.io.ByteArrayOutputStream;
import java.io.File;
import java.io.PrintStream;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.lang.reflect.Modifier;
import java.nio.file.Files;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

/**
 * Runs every script in tests/ through your Main and compares the output,
 * then checks a few design rules. Do not edit this file.
 *
 * Run it from the project folder (the one that contains src and tests).
 */
public class Grader
{
    public static void main(String[] args) throws Exception
    {
        // With no argument, everything runs. With an argument, only that check runs:
        //   a test name (or the start of one), like 03_errors or 03
        //   design  = only the design checks
        //   missing = only the missing script file test
        String only = args.length > 0 ? args[0].trim() : "";
        int failures = 0;

        if (only.isEmpty())
        {
            System.out.println("=== BEHAVIOR TESTS ===");
            failures += runScripts("");
            failures += runMissingFileTest();

            System.out.println();
            System.out.println("=== DESIGN CHECKS ===");
            failures += designChecks();
        }
        else if (only.equals("design"))
        {
            System.out.println("=== DESIGN CHECKS ===");
            failures += designChecks();
        }
        else if (only.equals("missing"))
        {
            System.out.println("=== BEHAVIOR TESTS ===");
            failures += runMissingFileTest();
        }
        else
        {
            System.out.println("=== BEHAVIOR TESTS (only: " + only + ") ===");
            failures += runScripts(only);
        }

        System.out.println();
        if (failures == 0)
            System.out.println("All checks passed.");
        else
            System.out.println(failures + " check(s) failed.");
        System.exit(failures == 0 ? 0 : 1);
    }

    /* ---------------- behavior tests ---------------- */

    private static int runScripts(String only) throws Exception
    {
        File dir = new File("tests");
        File[] files = dir.listFiles();
        if (files == null)
        {
            System.out.println("FAIL  could not find the tests folder. Run from the project folder.");
            return 1;
        }
        Arrays.sort(files);
        int failures = 0;
        int matched = 0;
        List<String> available = new ArrayList<>();
        for (File f : files)
        {
            if (!f.getName().endsWith(".txt"))
                continue;
            available.add(f.getName().replace(".txt", ""));
            if (!only.isEmpty() && !f.getName().startsWith(only))
                continue;
            File expected = new File(dir, f.getName().replace(".txt", ".expected"));
            if (!expected.exists())
                continue;
            List<String> want = Files.readAllLines(expected.toPath());
            List<String> got = runMain(f.getPath());
            failures += compare(f.getName(), want, got);
            matched++;
        }
        if (!only.isEmpty() && matched == 0)
        {
            System.out.println("FAIL  no test starts with \"" + only + "\". The tests are: " + available);
            return 1;
        }
        return failures;
    }

    private static int runMissingFileTest()
    {
        String path = "tests/does_not_exist.txt";
        List<String> want = new ArrayList<>();
        want.add("Error: could not open script file " + path + ".");
        return compare("missing script file", want, runMain(path));
    }

    private static List<String> runMain(String path)
    {
        PrintStream old = System.out;
        ByteArrayOutputStream buf = new ByteArrayOutputStream();
        String crash = null;
        try
        {
            System.setOut(new PrintStream(buf, true, "UTF-8"));
            library.app.Main.main(new String[] { path });
        }
        catch (Throwable t)
        {
            crash = t.toString();
        }
        finally
        {
            System.setOut(old);
        }
        List<String> lines = new ArrayList<>(Arrays.asList(buf.toString().split("\\R", -1)));
        if (crash != null)
            lines.add("(your program crashed: " + crash + ")");
        return lines;
    }

    private static List<String> clean(List<String> lines)
    {
        List<String> out = new ArrayList<>();
        for (String s : lines)
            out.add(s.replaceAll("\\s+$", ""));
        while (!out.isEmpty() && out.get(out.size() - 1).isEmpty())
            out.remove(out.size() - 1);
        return out;
    }

    private static int compare(String name, List<String> wantRaw, List<String> gotRaw)
    {
        List<String> want = clean(wantRaw);
        List<String> got = clean(gotRaw);
        int n = Math.max(want.size(), got.size());
        for (int i = 0; i < n; i++)
        {
            String w = i < want.size() ? want.get(i) : "(nothing)";
            String g = i < got.size() ? got.get(i) : "(nothing)";
            if (!w.equals(g))
            {
                System.out.println("FAIL  " + name);
                System.out.println("      first difference at output line " + (i + 1) + ":");
                System.out.println("      expected: " + w);
                System.out.println("      yours:    " + g);
                return 1;
            }
        }
        System.out.println("PASS  " + name);
        return 0;
    }

    /* ---------------- design checks ---------------- */

    private static int designChecks()
    {
        int failures = 0;

        Class<?> item = load("library.model.LibraryItem");
        if (item == null)
            return 1;

        failures += check(Modifier.isAbstract(item.getModifiers()),
            "LibraryItem is abstract",
            "LibraryItem must be declared abstract");

        List<Method> abstracts = new ArrayList<>();
        for (Method m : item.getDeclaredMethods())
            if (Modifier.isAbstract(m.getModifiers()))
                abstracts.add(m);
        failures += check(abstracts.size() >= 2,
            "LibraryItem declares at least 2 abstract methods (" + abstracts.size() + " found)",
            "LibraryItem must declare at least 2 abstract methods (the rules each kind of item decides)");

        boolean anyPublic = false;
        for (Method m : abstracts)
            if (Modifier.isPublic(m.getModifiers()))
                anyPublic = true;
        failures += check(!anyPublic && !abstracts.isEmpty(),
            "No abstract method is public: outside classes cannot call the rules directly",
            "An abstract method in LibraryItem is public (or there are none). Only the item and its subclasses should be able to call the rule methods.");

        String[] subs = { "Book", "Dvd", "Magazine" };
        List<Class<?>> checked = new ArrayList<>();
        checked.add(item);
        for (String s : subs)
        {
            Class<?> c = load("library.items." + s);
            if (c == null)
            {
                failures++;
                continue;
            }
            checked.add(c);
            failures += check(item.isAssignableFrom(c) && !Modifier.isAbstract(c.getModifiers()),
                s + " extends LibraryItem and is concrete",
                s + " must extend LibraryItem and must not be abstract");
        }

        Class<?> lib = load("library.app.Library");
        if (lib != null)
            checked.add(lib);
        Class<?> patron = loadQuiet("library.app.Patron");
        if (patron == null)
            patron = loadQuiet("library.model.Patron");
        if (patron != null)
            checked.add(patron);

        List<String> badFields = new ArrayList<>();
        for (Class<?> c : checked)
            for (Field f : c.getDeclaredFields())
            {
                if (f.isSynthetic())
                    continue;
                int mod = f.getModifiers();
                boolean constant = Modifier.isStatic(mod) && Modifier.isFinal(mod);
                if (!constant && !Modifier.isPrivate(mod))
                    badFields.add(c.getSimpleName() + "." + f.getName());
            }
        failures += check(badFields.isEmpty(),
            "All instance fields are private",
            "These fields are not private: " + badFields);

        Class<?> ex = load("library.model.LibraryException");
        if (ex != null)
            failures += check(Exception.class.isAssignableFrom(ex) && !RuntimeException.class.isAssignableFrom(ex),
                "LibraryException is a checked exception",
                "LibraryException must extend Exception (checked), not RuntimeException");
        else
            failures++;

        return failures;
    }

    private static int check(boolean ok, String pass, String fail)
    {
        if (ok)
        {
            System.out.println("PASS  " + pass);
            return 0;
        }
        System.out.println("FAIL  " + fail);
        return 1;
    }

    private static Class<?> loadQuiet(String name)
    {
        try
        {
            return Class.forName(name);
        }
        catch (ClassNotFoundException e)
        {
            return null;
        }
    }

    private static Class<?> load(String name)
    {
        Class<?> c = loadQuiet(name);
        if (c == null)
            System.out.println("FAIL  class " + name + " was not found (check the package and the name)");
        return c;
    }
}
